import copy,unittest
from explainer.retention import audit,content_hash,require

def fixture():
    plan={'shots':[{'id':'a','duration':20,'narration':'Which choice matters? You will learn to trace it. Waiting leaves room.'},
                   {'id':'b','duration':20,'narration':'What survives? The road user stays visible. The branch is removed.'}],
          'claims':{'c':{'status':'verified','sources':['primary']}},'sources':{'primary':{'supports':'Synthetic test source'}}}
    plan['retention']={'version':1,'timing_basis':'estimated',
       'opening':{'viewer_value':'Trace a candidate','visual_action':'Show the conflict','reason_to_care':'Avoid confusing decisions with agents',
                  'value_promise':{'shot':'a','at':2,'quote':'You will learn to trace it.'}},
