"""Revised visual rhythm: eight directed shots, actual 3D reveal, evolving explanation."""
from pathlib import Path
from functools import lru_cache
import math,subprocess
from PIL import Image,ImageDraw,ImageFont,ImageEnhance
from explainer.core import read,write
from explainer.media import check_video
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'build/motion-v2';OUT.mkdir(parents=True,exist_ok=True)
PRE=ROOT/'build/preview';AUD=ROOT/'build/voice-audition';W,H=960,540
CUTS=[0,.12,.23,.35,.49,.62,.76,.89,1]
WHITE='#eff6ff';CYAN='#65dcf6';GRAY='#9ebacc';DARK='#091726'
@lru_cache(None)
def font(n,bold=False):return ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans'+('-Bold' if bold else '')+'.ttf',n)
@lru_cache(130)
def image(path):
 with Image.open(path) as im:return im.convert('RGB').resize((W,H),Image.Resampling.LANCZOS)

def move(im,t,zoom=.05,pan=.025):
 # Small editorial moves over rendered 3D plates; real object motion is rendered separately.
 scale=1+zoom*t;w,h=round(W*scale),round(H*scale)
 im=im.resize((w,h),Image.Resampling.BICUBIC)
 x=max(0,min(w-W,round((w-W)*(.5+pan*(t-.5)))))
 y=max(0,min(h-H,round((h-H)*.45)))
 return im.crop((x,y,x+W,y+H))

@lru_cache(None)
def shade(amount):
 mask=Image.new('RGBA',(W,H));d=ImageDraw.Draw(mask)
 for x in range(W):d.line((x,0,x,H),fill=(4,12,23,int(amount*(1-x/W)**1.5+10)))
 return mask

def background(path,local,dim=220):return Image.alpha_composite(move(image(str(path)).copy(),local).convert('RGBA'),shade(dim)).convert('RGB')

def lines(d,text,x,y,size=38,width=460,color=WHITE):
 words=text.split();row='';rows=[]
 for word in words:
  test=(row+' '+word).strip()
  if d.textlength(test,font=font(size,True))>width and row:rows.append(row);row=word
  else:row=test
 if row:rows.append(row)
 for i,row in enumerate(rows):d.text((x,y+i*(size+8)),row,font=font(size,True),fill=color)

def progress_line(d,points,amount,color,width=3):
 amount=max(0,min(1,amount));lengths=[math.dist(a,b) for a,b in zip(points,points[1:])];remaining=sum(lengths)*amount
 for a,b,length in zip(points,points[1:],lengths):
  if remaining<=0:break
  portion=min(1,remaining/length);end=(a[0]+(b[0]-a[0])*portion,a[1]+(b[1]-a[1])*portion)
  d.line([a,end],fill=color,width=width);remaining-=length

def graph(d,local,mode):
 root=(552,279);candidates=[(782,145),(805,280),(782,416)];scores=[.82,.46,.13]
 for i,((x,y),score) in enumerate(zip(candidates,scores)):
  reveal=max(0,min(1,local*3.5-i*.18)) if mode=='organize' else 1
  if mode=='prune' and i>0:reveal=max(0,1-local*1.8)
  path=[root,(650,y),(x-69,y)]
  progress_line(d,path,reveal,CYAN if i==0 and mode!='organize' else '#5f8da6',3)
  if reveal>.85 or (mode=='prune' and i>0 and reveal>.03):
   color=CYAN if i==0 and mode!='organize' else '#678a9e'
   d.rounded_rectangle((x-67,y-29,x+67,y+29),radius=12,fill=DARK,outline=color,width=2)
   label=f'OPTION {i+1}' if mode=='organize' else f'{score*(min(1,local*2.5) if mode=="score" else 1):.2f}'
   d.text((x-43,y-10),label,font=font(16,True),fill=WHITE)
 d.ellipse((root[0]-29,root[1]-29,root[0]+29,root[1]+29),fill=DARK,outline=CYAN,width=3)
 d.text((root[0]-20,root[1]-7),'GOAL',font=font(11,True),fill=WHITE)
 if mode=='score':d.text((551,466),'Illustrative scores · not Tesla measurements',font=font(11),fill=GRAY)
 if mode=='prune':d.text((550,466),'Example threshold: 0.50',font=font(12),fill=GRAY)
 # A traveling signal gives the viewer an action to follow on the relevant branch.
 u=(local*.5)%1;path=[root,(650,145),(713,145)];lengths=[math.dist(a,b) for a,b in zip(path,path[1:])];distance=u*sum(lengths)
 for a,b,length in zip(path,path[1:],lengths):
