 if stage==0:
  idx=min(89,round(local*100));im=background(PRE/'car'/f'{idx:06d}.png',local)
 elif stage==3:
  idx=min(17,round(local*48));im=background(OUT/'chip'/f'{idx:06d}.png',local,150)
