 else:im=background(PRE/'compute.png',local)
 d=ImageDraw.Draw(im)
 d.text((47,31),'INSIDE TESLA’S PLANNING PATENT',font=font(12,True),fill=CYAN)
 if stage==0:
  lines(d,'Can software help older hardware do more?',48,114,38,465)
 elif stage==1:
  lines(d,'Make the planning more selective.',48,112,39,440)
  d.text((50,282),'Smarter search starts with the choices.',font=font(15),fill=GRAY)
 elif stage==2:
