 elif stage in (3,4,5):
  titles={3:'Organize the choices.',4:'Score the alternatives.',5:'Stop exploring poor branches.'}
  lines(d,titles[stage],48,116,38,410)
  captions={3:'Reveal the planning problem.',4:'Compare coherent candidate paths.',5:'Keep developing useful candidates.'}
  d.text((50,280),captions[stage],font=font(14),fill=GRAY)
  graph(d,local,{3:'organize',4:'score',5:'prune'}[stage])
  if stage==3:d.text((50,317),'Illustrative exploded compute module',font=font(11),fill=GRAY)
 elif stage==6:
  lines(d,'Keep the evidence clear.',48,112,38,430)
  for index,(title,sub,color) in enumerate([('Planning method','Disclosed in the patent',CYAN),('HW3 feature parity','Not established by this document','#e8be73')]):
   reveal=max(0,min(1,local*3-index*.45));y=255+index*104+round((1-reveal)*15)
   if reveal<=0:continue
   d.rounded_rectangle((48,y,521,y+80),radius=10,fill=DARK,outline='#2c4c63')
   d.rectangle((48,y+12,52,y+68),fill=color)
   d.text((68,y+14),title,font=font(18,True),fill=WHITE)
   d.text((68,y+46),sub,font=font(13),fill=color)
 else:
  lines(d,'Let’s look at how it works.',48,116,40,440)
  d.text((50,285),'A source-backed engineering explanation.',font=font(15),fill=GRAY)
 d.text((48,503),'US20260105614A1 · Original illustrative 3D models',font=font(11),fill='#92adbf')
 return im

def main():
 comparison=read(AUD/'comparison.json')
 assert len(list((OUT/'chip').glob('*.png')))==18
 for key,metadata in comparison['auditions'].items():
  total=metadata['seconds'];nf=round(total*30);silent=OUT/f'silent-{key}.mp4';logfile=OUT/f'encode-{key}.log'
  with logfile.open('w') as log:
   process=subprocess.Popen(['ffmpeg','-v','error','-y','-f','rawvideo','-pix_fmt','rgb24','-s','960x540','-r','30','-i','-',
    '-c:v','libx264','-threads','2','-preset','medium','-crf','19','-pix_fmt','yuv420p',str(silent)],stdin=subprocess.PIPE,stderr=log)
   try:
    for frame in range(nf):process.stdin.write(render_frame(frame/30,total).tobytes())
   finally:process.stdin.close();code=process.wait()
