    o=bpy.context.object;o.name=name;o.parent=parent;o.data.materials.append(mat);return o


def clone(source,name,parent=None):
    o=source.copy();o.name=name;bpy.context.collection.objects.link(o);o.parent=parent
    for child in source.children:clone(child,name+' '+child.name,o)
