"""Reusable ideal slider-crank kinematics. No combustion or force simulation."""
import math


def positions(angle, radius=.7, rod_length=2.7, center_z=.75):
    if not all(math.isfinite(v) for v in (angle, radius, rod_length, center_z)) or not 0 < radius < rod_length:
        raise ValueError('Use finite values with 0 < crank radius < connecting-rod length')
    x = radius * math.sin(angle)
    z = center_z + radius * math.cos(angle)
    slider_z = z + math.sqrt(rod_length**2 - x**2)
    return (x, 0, z), (0, 0, slider_z)

"""Free/commercial asset records, contained model packages, and generated credits."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
import shlex
import shutil
import struct
import tempfile
from urllib.parse import unquote, urlsplit

FORMATS = {'.glb', '.gltf', '.obj', '.stl'}
LICENSES = {
    'CC0-1.0': 'https://creativecommons.org/publicdomain/zero/1.0/',
    'CC-BY-4.0': 'https://creativecommons.org/licenses/by/4.0/',
    'LicenseRef-Public-Domain': None,
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def inside(root, name):
    path = (Path(root) / name).resolve()
    if not path.is_relative_to(Path(root).resolve()):
        raise ValueError(f'Model dependency escapes its package: {name}')
    if not path.is_file():
        raise ValueError(f'Missing model dependency: {name}')
    return path


def rights_errors(rights):
    errors = []
    if rights.get('license') not in LICENSES:
        errors.append('Only CC0-1.0, CC-BY-4.0 or reviewed public-domain assets are supported; NC/ND/editorial/unknown licenses are blocked')
    if type(rights.get('price')) not in (int, float) or rights.get('price') != 0:
        errors.append('Asset must be free to obtain (price 0)')
    for key in ('commercial_use', 'modification_allowed'):
        if rights.get(key) is not True:
            errors.append(f'License review must confirm {key}')
    for key in ('title', 'creator', 'source_url', 'license_url', 'accessed', 'review_notes'):
        if not isinstance(rights.get(key), str) or not rights[key].strip():
            errors.append(f'License record requires {key}')
    if rights.get('rights_review') != 'approved':
        errors.append('Source-specific rights review is required; a library-wide license is insufficient')
    for key in ('source_url', 'license_url'):
        if urlsplit(rights.get(key, '')).scheme != 'https':
            errors.append(f'{key} must be an HTTPS source/evidence link')
    canonical = LICENSES.get(rights.get('license'))
    if canonical and rights.get('license_url', '').rstrip('/') not in (canonical.rstrip('/'), canonical+'legalcode'):
        errors.append('License URL must match the declared CC0/CC BY license')
    if rights.get('license') == 'LicenseRef-Public-Domain' and not rights.get('public_domain_basis'):
        errors.append('Public-domain records need the source-specific legal basis')
    if rights.get('license') == 'CC-BY-4.0':
        if not rights.get('attribution'):
            errors.append('CC BY assets require attribution text')
        if not rights.get('changes'):
            errors.append('CC BY assets require an explicit changes/modifications statement')
    if rights.get('additional_restrictions') != []:
        errors.append('Additional/unknown restrictions need review; use another compatible asset')
    return errors


def gltf_document(path):
    path = Path(path)
    if path.suffix.lower() == '.gltf':
        return json.loads(path.read_text())
    raw = path.read_bytes()
    if len(raw) < 20:
        raise ValueError('Truncated GLB')
    magic, version, length = struct.unpack_from('<4sII', raw)
    if magic != b'glTF' or version != 2 or length != len(raw):
        raise ValueError('Expected a complete glTF 2 binary file')
    size, kind = struct.unpack_from('<I4s', raw, 12)
    if kind != b'JSON' or 20 + size > len(raw):
        raise ValueError('GLB JSON chunk missing or truncated')
    return json.loads(raw[20:20+size])


def dependencies(model):
    """Discover every URI/material/texture file before Blender touches a package."""
    model = Path(model).resolve()
    root, found = model.parent, {model}
    def resource(reference, parent=root):
        if reference.startswith('data:'):
            return None
        parsed = urlsplit(reference)
        decoded = unquote(parsed.path)
        if parsed.scheme or parsed.netloc or parsed.query or parsed.fragment or '\\' in decoded or Path(decoded).is_absolute():
            raise ValueError(f'Only contained local resources are supported: {reference}')
        path = inside(root, Path(parent).relative_to(root) / decoded)
        found.add(path)
        return path
    if model.suffix.lower() in ('.gltf', '.glb'):
        doc = gltf_document(model)
        def walk(value):
            if isinstance(value, dict):
                for key, item in value.items():
                    if key == 'uri' and isinstance(item, str):
                        resource(item)
                    else:
                        walk(item)
            elif isinstance(value, list):
                for item in value: walk(item)
        walk(doc)
    elif model.suffix.lower() == '.obj':
        for line in model.read_text().splitlines():
            words = shlex.split(line, comments=True)
            if not words or words[0].lower() != 'mtllib': continue
            for name in words[1:]:
                material = resource(name)
                for entry in material.read_text().splitlines():
                    tokens = shlex.split(entry, comments=True)
                    if tokens and (tokens[0].lower().startswith('map_') or tokens[0].lower() in ('bump', 'disp', 'decal', 'norm', 'refl')):
                        if len(tokens) < 2 or tokens[1].startswith('-'):
                            raise ValueError('OBJ texture options are unsupported; package as GLB or simplify the MTL reference')
                        resource(' '.join(tokens[1:]), material.parent)
    return sorted(found)


def model_errors(asset, root=None):
    errors = rights_errors(asset.get('rights', {}))
    if Path(asset.get('path', '')).suffix.lower() not in FORMATS:
        errors.append('Model must be GLB, glTF, OBJ or STL; executable scene files are not accepted')
    meters = asset.get('meters_per_unit')
    if isinstance(meters, bool) or not isinstance(meters, (int, float)) or not 0 < meters < float('inf'):
        errors.append('Record a finite positive meters_per_unit')
    if not asset.get('units_notes'):
        errors.append('Record the source/assumption for model units')
    if not isinstance(asset.get('files'), dict) or not asset['files']:
        errors.append('Model package requires a complete file checksum manifest')
    if root is not None and not errors:
        try:
            model = inside(root, asset['path'])
            package = {str(p.relative_to(Path(root).resolve())) for p in dependencies(model)}
            evidence = asset.get('license_evidence', '')
            if not evidence:
                raise ValueError('Retain source-specific license evidence in the project')
            expected = package | {evidence}
            if set(asset['files']) != expected:
                raise ValueError('Package manifest does not exactly match model dependencies and license evidence')
            for name, expected_hash in asset['files'].items():
                if sha(inside(root, name)) != expected_hash:
                    raise ValueError(f'Model package bytes changed: {name}')
        except (ValueError, OSError, json.JSONDecodeError) as exc:
            errors.append(str(exc))
    return errors


def register_model(root, asset_id, model, rights, evidence, meters_per_unit, units_notes):
    """Stage and copy a local reviewed package; visual review remains pending."""
    from .core import read, write
    root = Path(root).resolve()
    plan = read(root / 'plan.json')
    if not asset_id or not asset_id.isascii() or not asset_id.replace('_', '').replace('-', '').isalnum():
        raise ValueError('Asset ID must contain ASCII letters, digits, underscores or hyphens')
    errors = rights_errors(rights)
    if errors: raise ValueError('\n'.join(errors))
    model, evidence = Path(model).resolve(), Path(evidence).resolve()
    if model.suffix.lower() not in FORMATS: raise ValueError('Unsupported model format')
    if not evidence.is_file() or not evidence.stat().st_size: raise ValueError('Local license evidence is required')
    if rights.get('download_sha256') and sha(model) != rights['download_sha256']:
        raise ValueError('Downloaded model does not match the reviewed source checksum')
    files = dependencies(model)
    destination = root / 'assets' / asset_id
    if not destination.resolve().is_relative_to(root):
        raise ValueError('Asset destination escapes project directory')
    if asset_id in plan.get('assets', {}) or destination.exists():
        raise ValueError('Asset ID or destination already exists; refusing to overwrite')
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=destination.parent, prefix='.stage-') as temp:
        stage = Path(temp) / asset_id
        for file in files:
            target = stage / 'source' / file.relative_to(model.parent)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(file, target)
        shutil.copyfile(evidence, stage / 'license-evidence.txt')
        relative = Path('assets') / asset_id
        record = {'kind': 'model', 'path': str(relative / 'source' / model.name), 'sha256': sha(model),
                  'review': 'pending', 'provenance': rights['source_url'], 'rights': rights,
                  'meters_per_unit': meters_per_unit, 'units_notes': units_notes,
                  'license_evidence': str(relative / 'license-evidence.txt'),
                  'files': {str(relative / p.relative_to(stage)): sha(p) for p in sorted(stage.rglob('*')) if p.is_file()}}
        # Check before publishing the staged package; main-file units must also be valid.
        check = model_errors(record)
        if check: raise ValueError('\n'.join(check))
        stage.rename(destination)
        try:
            check = model_errors(record, root)
            if check: raise ValueError('\n'.join(check))
            plan.setdefault('assets', {})[asset_id] = record
            write(root / 'plan.json', plan)
        except Exception:
            shutil.rmtree(destination)
            raise
    return record


def credits(plan):
    lines = ['# Asset credits', '', 'Keep applicable credits with the published video description.', '']
    for key, asset in sorted(plan.get('assets', {}).items()):
        if asset.get('kind') != 'model': continue
        r = asset['rights']
        lines.extend([f'## {r["title"]} ({key})', '', f'Creator: {r["creator"]}',
                      f'Source: {r["source_url"]}', f'License: {r["license"]} — {r["license_url"]}',
                      f'Changes: {r.get("changes", "None recorded; update before release if modified.")}', ''])
        if r.get('attribution'): lines.extend([r['attribution'], ''])
    return '\n'.join(lines) + '\n'

"""Original generic compute-module prop with a reusable exploded-processor rig."""
import bpy
from .traffic_scene import cube
from .visual_tools import material,line


def build_compute(name='Compute'):
    root=bpy.data.objects.new(name,None);bpy.context.collection.objects.link(root)
    core=bpy.data.objects.new(name+' processor rig',None);bpy.context.collection.objects.link(core);core.parent=root
    pcb=material(name+' PCB',(.025,.11,.095,1));chip=material(name+' packages',(.035,.045,.065,1))
    metal=material(name+' lid',(.35,.42,.5,1));gold=material(name+' conductors',(.55,.32,.075,1))
    white=material(name+' connectors',(.65,.69,.74,1))
    pieces=[]
    def part(label,pos,size,mat,parent=root,bevel=.025):
        obj=cube(name+' '+label,pos,size,mat,parent,bevel);pieces.append(obj);return obj
    part('board',(0,0,0),(5,3.7,.12),pcb,bevel=.05)
    part('processor',(0,0,.21),(1.65,1.65,.32),chip,core,.06)
    part('cap',(0,0,.39),(1.42,1.42,.06),metal,core,.04)
    for sign in [-1,1]:
        for i in range(12):
            a=-.66+i*.12
            part('contact',(sign*.88,a,.17),(.2,.045,.055),gold,core,.005)
            part('contact',(a,sign*.88,.17),(.045,.2,.055),gold,core,.005)
        for y in [-1.15,1.15]:part('memory',(sign*1.6,y,.2),(.62,.62,.26),chip)
    for i in range(8):
        x=-2.1+i*.2
        part('passive',(x,-1.55,.12),(.10,.18,.12),metal,bevel=.01)
        obj=line(name+' trace',[(x,1.55,.07),(x,.95,.07),(-.8,.95,.07)],.012,gold);obj.parent=root;pieces.append(obj)
    for x in [-1.8,-.9,0,.9,1.8]:part('connector',(x,1.77,.2),(.55,.20,.3),white)
    for x in [-2.15,2.15]:
        for y in [-1.4,1.4]:part('mount',(x,y,-.15),(.14,.14,.18),gold)
    return root,core,pieces

"""Explicit chat-reviewed approval/rejection records; isolated from Grandpa's render queue."""
from pathlib import Path
import shutil
from .core import contained,digest,read,write
from .assets import sha


def prepare_packet(project,video,qa_path):
    project=Path(project).resolve();video=Path(video).resolve();qa_path=Path(qa_path).resolve()
    if not video.is_relative_to(project) or not qa_path.is_relative_to(project):raise ValueError('Review artifacts must be inside project')
    qa=read(qa_path)
    if not qa.get('passed') or qa.get('review')!='passed':raise ValueError('Automated and actual visual review must pass first')
    engine=Path(__file__).parent
    sources=[*engine.glob('*.py'),*engine.glob('bibles/*.md'),*project.glob('*.py'),project/'plan.json']
    packet={'status':'awaiting_user','options':['send_to_work_pool','reject'],
            'video':str(video.relative_to(project)),'qa':str(qa_path.relative_to(project)),
            'video_sha256':sha(video),'qa_sha256':sha(qa_path),
            'source_hashes':{str(p.resolve()):sha(p) for p in sources},
            'note':'Preview direction approval. Full production assets and preflight must still be completed; this is not a ready-to-run Grandpa render job.'}
    packet['id']=digest(packet)[:16];write(project/'review/decision.json',packet)
    return packet


def decide(project,choice,user_evidence,notes='',pool_root=None):
    if choice not in ('send_to_work_pool','reject') or not user_evidence.strip():raise ValueError('Record an actual user decision and its evidence')
    project=Path(project).resolve();path=project/'review/decision.json';packet=read(path)
    if packet['status']!='awaiting_user':raise ValueError('Decision already recorded')
    if choice=='reject':
        packet.update({'status':'rejected','user_evidence':user_evidence,'notes':notes});write(path,packet);return path
    for source,expected in packet['source_hashes'].items():
        if sha(source)!=expected:raise ValueError('Preview sources changed; present a fresh review')
    video=contained(project,packet['video']);qa=contained(project,packet['qa'])
    if sha(video)!=packet['video_sha256'] or sha(qa)!=packet['qa_sha256']:raise ValueError('Reviewed artifacts changed')
    output=(Path(pool_root) if pool_root is not None else Path(__file__).parent/'work_pool')/packet['id']
    if output.exists():raise ValueError('Work item already exists')
    output.mkdir(parents=True)
    try:
        shutil.copy2(video,output/'approved-preview.mp4');shutil.copy2(qa,output/'preview-qa.json')
        shutil.copy2(project/'plan.json',output/'plan.json')
        snapshot=output/'source-snapshot';snapshot.mkdir()
        for source in packet['source_hashes']:
            src=Path(source)
            if src.is_relative_to(Path(__file__).parent):relative=src.relative_to(Path(__file__).parent)
            else:relative=Path('external-source')/src.name
            target=snapshot/relative;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,target)
        write(output/'manifest.json',{'kind':'explainer_project','status':'approved_direction_requires_production_preflight',
               'project':str(project),'review':packet,'user_evidence':user_evidence,
               'next_steps':'Complete the remaining source-backed chapters/assets, fit frozen narration, self-check, then render the authorized full video. Preserve approved visual direction; ask about material creative changes.'})
    except Exception:
        shutil.rmtree(output);raise
    packet.update({'status':'sent_to_work_pool','user_evidence':user_evidence,'work_item':str(output)})
    write(path,packet);return output

"""Subject-dependent defaults; explicit shot choices remain part of storyboard approval."""
THEMES = {
    'dark': {'background': (.025, .03, .04, 1), 'ink': (.92, .95, 1, 1),
             'structure': (.3, .34, .4, 1), 'active': (.9, .25, .08, 1),
             'flow': (.04, .45, .95, 1), 'signal': (1, .7, .08, 1),
             'context': (.43, .46, .52, 1), 'section': (.55, .59, .64, 1)},
    'light': {'background': (.85, .88, .92, 1), 'ink': (.015, .025, .04, 1),
              'structure': (.12, .16, .22, 1), 'active': (.65, .09, .025, 1),
              'flow': (.015, .16, .5, 1), 'signal': (.38, .19, .015, 1),
              'context': (.28, .32, .38, 1), 'section': (.48, .52, .58, 1)}}


def resolve_theme(shot):
    selected = shot.get('presentation', {}).get('background', 'auto')
    if selected == 'auto':
        # Readability starting points, not an assertion that shot accuracy predicts best art direction.
        selected = 'dark' if shot.get('accuracy') == 'literal' else 'light'
    if selected not in THEMES:
        raise ValueError(f'Unknown background {selected}')
    return selected, dict(THEMES[selected])

"""Versioned production contracts and approval evidence (standard library only)."""
from __future__ import annotations
import hashlib
import json
import math
from pathlib import Path

VERSION = 1
VOICE = {"engine": "kokoro-onnx", "voice": "am_fenrir", "speed": 0.8, "sample_rate": 48000}
VOICE_DELIVERY = {"sentence_pause": 0.18, "clause_pause": 0.06}
ROLES = {"structure", "active", "flow", "signal", "context"}


def read(path):
    return json.loads(Path(path).read_text())


def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    temp.write_text(json.dumps(value, indent=2) + '\n')
    temp.replace(path)


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def contained(root, relative):
    path = (Path(root) / relative).resolve()
    if not path.is_relative_to(Path(root).resolve()):
        raise ValueError(f'Asset escapes project directory: {relative}')
    return path


def finite(value):
    return isinstance(value, (float, int)) and not isinstance(value, bool) and math.isfinite(value)


def vector(value, n=3):
    return isinstance(value, list) and len(value) == n and all(finite(x) for x in value)


def validate(plan, root=None):
    """Return actionable blockers. Drafts may be incomplete; production contracts may not."""
    errors = []
    if plan.get('version') != VERSION:
        errors.append('Unsupported plan version')
    if not isinstance(plan.get('title'), str) or not plan['title'].strip():
        errors.append('Supply a project title')
    if plan.get('format') != {'width': 1920, 'height': 1080, 'fps': 30, 'captions': False}:
        errors.append('Format must be 1920x1080, 30 fps, without burned-in captions')
    if plan.get('narrator') != VOICE:
        errors.append('Use the channel narrator profile; changing it requires a direction decision')
    if plan.get('audio_policy') != {'music': False, 'sfx': 'restrained_mechanical'}:
        errors.append('Audio must use restrained mechanical effects and no music')
    if not plan.get('learning_goal'):
        errors.append('Codex must complete the learning goal')
    if plan.get('open_questions'):
        errors.append('Resolve outstanding direction questions')
    subject_bible = plan.get('subject_bible', {})
    for key in ('scope', 'mechanism', 'terminology', 'narration_guidance', 'simplifications'):
        if not subject_bible.get(key):
            errors.append(f'Codex must complete subject bible: {key}')
    sources = plan.get('sources', {})
    claims = plan.get('claims', {})
    assets = plan.get('assets', {})
    for key, claim in claims.items():
        if claim.get('status') != 'verified' or not claim.get('sources'):
            errors.append(f'Claim {key}: verify against sources before production')
        for source in claim.get('sources', []):
            entry = sources.get(source, {})
            if not all(entry.get(k) for k in ('title', 'locator', 'accessed', 'supports')):
                errors.append(f'Claim {key}: source {source} lacks a locator/date/supporting evidence')
    for key, asset in assets.items():
        if asset.get('kind') not in ('image', 'model'):
            errors.append(f'Asset {key}: unsupported kind')
        if asset.get('review') != 'approved' or not asset.get('provenance'):
            errors.append(f'Asset {key}: requires accuracy/provenance review')
        if asset.get('kind') == 'model':
            from .assets import model_errors
            errors.extend(f'Asset {key}: {message}' for message in model_errors(asset, root))
        if root is not None:
            try:
                path = contained(root, asset.get('path', ''))
                if not path.is_file():
                    errors.append(f'Asset {key}: file missing')
                elif asset.get('sha256') != hashlib.sha256(path.read_bytes()).hexdigest():
                    errors.append(f'Asset {key}: bytes changed; review and update its SHA-256')
            except ValueError as exc:
                errors.append(str(exc))
    shots = plan.get('shots', [])
    if not shots:
        errors.append('Codex must complete the shot list from the supplied plan')
    ids = set()
    for shot in shots:
        sid = shot.get('id', '')
        prefix = f'Shot {sid or "<missing>"}'
        if not sid or not isinstance(sid, str) or not sid.replace('_', '').replace('-', '').isalnum() or sid in ids:
            errors.append(f'{prefix}: needs a unique alphanumeric ID')
        ids.add(sid)
        duration = shot.get('duration')
        if not finite(duration) or duration <= 0:
            errors.append(f'{prefix}: duration must be positive and finite')
        for key in ('narration', 'teaches', 'visual_intent'):
            if not isinstance(shot.get(key), str) or not shot[key].strip():
                errors.append(f'{prefix}: complete {key}')
        if shot.get('accuracy') not in ('literal', 'schematic', 'analogy'):
            errors.append(f'{prefix}: declare literal, schematic, or analogy')
        if shot.get('accuracy') != 'literal' and not shot.get('simplifications'):
            errors.append(f'{prefix}: record simplifications')
        if not shot.get('claim_ids') and not shot.get('nonfactual_reason'):
            errors.append(f'{prefix}: link factual claims or explain why this shot is nonfactual')
        for claim in shot.get('claim_ids', []):
            if claim not in claims:
                errors.append(f'{prefix}: unknown claim {claim}')
        for cue in shot.get('sfx', []):
            if (cue.get('kind') not in ('click', 'clunk', 'motor') or not cue.get('purpose') or
                not finite(cue.get('at')) or not finite(cue.get('duration')) or
                not finite(duration) or cue.get('at', -1) < 0 or cue.get('duration', 0) <= 0 or
                cue.get('at', 0) + cue.get('duration', 0) > duration):
                errors.append(f'{prefix}: invalid or unexplained mechanical sound cue')
        presentation = shot.get('presentation', {})
        if presentation.get('background', 'auto') not in ('auto', 'light', 'dark'):
            errors.append(f'{prefix}: background must be auto, light or dark')
        if presentation.get('background', 'auto') != 'auto' and not presentation.get('reason'):
            errors.append(f'{prefix}: explain the explicit background choice')
        components = shot.get('components', [])
        component_ids = set()
        for obj in components:
            oid = obj.get('id')
            if not oid or oid in component_ids:
                errors.append(f'{prefix}: duplicate/missing component ID')
            component_ids.add(oid)
            if obj.get('shape') not in ('box', 'cylinder', 'sphere', 'tube', 'model') or obj.get('role') not in ROLES:
                errors.append(f'{prefix}/{oid}: unsupported shape or semantic role')
            if obj.get('shape') == 'model':
                asset_id = obj.get('asset_id')
                if assets.get(asset_id, {}).get('kind') != 'model':
                    errors.append(f'{prefix}/{oid}: model component needs a registered model asset')
                if asset_id not in shot.get('asset_ids', []):
                    errors.append(f'{prefix}/{oid}: declare model asset_id in shot asset_ids')
                if not finite(obj.get('scale', 1)) or obj.get('scale', 1) <= 0:
                    errors.append(f'{prefix}/{oid}: model scale must be positive and uniform')
                if 'section' in obj or 'size' in obj:
                    errors.append(f'{prefix}/{oid}: imported models use uniform scale; general model sections are not implemented')
            wall = obj.get('wall', .12)
            if obj.get('shape') == 'tube' and (not finite(wall) or not 0 < wall < .5):
                errors.append(f'{prefix}/{oid}: tube wall must be between 0 and 0.5')
            if 'section' in obj:
                cut = obj['section']
                if (cut.get('axis') not in ('x', 'y', 'z') or
                    cut.get('keep') not in ('positive', 'negative') or
                    not finite(cut.get('offset', 0)) or not -.5 < cut.get('offset', 0) < .5):
                    errors.append(f'{prefix}/{oid}: invalid local section plane')
                if obj.get('shape') == 'tube' and cut.get('axis') == 'z':
                    errors.append(f'{prefix}/{oid}: tube sections currently support x/y only to preserve the bore')
            for field in (('position',) if obj.get('shape') == 'model' else ('position', 'size')):
                if not vector(obj.get(field)) or (field == 'size' and min(obj[field]) <= 0):
                    errors.append(f'{prefix}/{oid}: invalid {field}')
            for field in ('move_to', 'rotation', 'rotate_to'):
                if field in obj and not vector(obj[field]):
                    errors.append(f'{prefix}/{oid}: invalid {field}')
        flow_ids = set()
        for cue in shot.get('flows', []):
            path = cue.get('path', [])
            radius = cue.get('radius', .025)
            if (not cue.get('id') or cue['id'] in flow_ids or not cue.get('explains') or
                cue.get('role', 'flow') not in ROLES or not isinstance(path, list) or len(path) < 2 or
                not all(vector(point) for point in path) or
                not finite(radius) or radius <= 0):
                errors.append(f'{prefix}: invalid or unexplained flow arrow')
            elif any(a == b for a, b in zip(path, path[1:])):
                errors.append(f'{prefix}: consecutive flow points must be distinct')
            flow_ids.add(cue.get('id'))
        visual_assets = shot.get('asset_ids', [])
        for aid in visual_assets:
            if aid not in assets:
                errors.append(f'{prefix}: unknown asset {aid}')
        mode = shot.get('visual_type', 'assembly')
        if mode == 'image' and (shot.get('flows') or shot.get('labels') or shot.get('components')):
            errors.append(f'{prefix}: image shots cannot silently ignore 3D overlays')
        if mode == 'image':
            if len(visual_assets) != 1 or assets.get(visual_assets[0], {}).get('kind') != 'image':
                errors.append(f'{prefix}: image shot requires exactly one image asset')
        elif mode == 'assembly':
            if not components:
                errors.append(f'{prefix}: assembly needs subject-specific components')
            referenced = {obj.get('asset_id') for obj in components if obj.get('shape') == 'model'}
            if set(visual_assets) != referenced:
                errors.append(f'{prefix}: assembly asset_ids must match its model component references')
        else:
            errors.append(f'{prefix}: unsupported visual_type {mode}')
        for label in shot.get('labels', []):
            if not label.get('text') or not vector(label.get('position')):
                errors.append(f'{prefix}: invalid technical label')
            if label.get('target') and label['target'] not in component_ids:
                errors.append(f'{prefix}: callout targets unknown component {label["target"]}')
            if not finite(label.get('size', .18)) or label.get('size', .18) <= 0:
                errors.append(f'{prefix}: invalid label size')
        camera = shot.get('camera', {})
        if not all(vector(camera.get(k)) for k in ('position', 'target')):
            errors.append(f'{prefix}: camera needs position and target vectors')
        elif camera['position'] == camera['target']:
            errors.append(f'{prefix}: camera position equals target')
        if 'end_position' in camera and not vector(camera['end_position']):
            errors.append(f'{prefix}: invalid camera end_position')
        if not finite(camera.get('lens', 50)) or camera.get('lens', 50) <= 0:
            errors.append(f'{prefix}: camera lens must be positive')
    return errors


def fingerprint(plan, root):
    """Bind approvals to plan, local asset bytes, code and bibles, not mutable filenames."""
    files = {}
    for key, asset in plan.get('assets', {}).items():
        path = contained(root, asset['path'])
        files[f'asset:{key}'] = hashlib.sha256(path.read_bytes()).hexdigest()
        for name in asset.get('files', {}):
            related = contained(root, name)
            files[f'asset:{key}:{name}'] = hashlib.sha256(related.read_bytes()).hexdigest()
    here = Path(__file__).parent
    for path in sorted([*here.glob('*.py'), *here.glob('bibles/*.md')]):
        files[str(path.relative_to(here))] = hashlib.sha256(path.read_bytes()).hexdigest()
    return digest({'plan': plan, 'files': files})


def storyboard(plan):
    bible = plan.get('subject_bible', {})
    lines = [f'# {plan["title"]}', '', f'Learning goal: {plan.get("learning_goal", "UNRESOLVED")}', '',
             '## Subject bible', '', *[f'- {key}: {value}' for key, value in bible.items()], '',
             '## Storyboard', '',
             '| Time | Shot | Narration | What viewers learn | Visual |', '|---|---|---|---|---|']
    t = 0
    from .presentation import resolve_theme
    for shot in plan.get('shots', []):
        end = t + shot['duration']
        cells = [f'{t:.2f}–{end:.2f}s', shot['id'], shot['narration'], shot['teaches'], shot['visual_intent'] + (' [image preserved]' if shot.get('visual_type') == 'image' else f' [background: {resolve_theme(shot)[0]}]')]
        lines.append('| ' + ' | '.join(str(c).replace('|', '\\|').replace('\n', ' ') for c in cells) + ' |')
        t = end
    return '\n'.join(lines) + '\n'

"""Checked kinematics for an illustrative yield-then-left-turn scene, not a driving policy."""
import math


def smooth(t):
    t=max(0,min(1,t));return t*t*(3-2*t)


def pose(t,duration):
    wait=6.7;end=duration-.35
    if duration<=wait+.5:raise ValueError('Allow time for the crossing and the turn')
    progress=smooth((t-wait)/(end-wait))
    straight=6.;radius=4.3;arc=radius*math.pi/2;exit_length=8.5
    distance=progress*(straight+arc+exit_length)
    if distance<=straight:
        x,y,yaw=1.8,-8.5+distance,0.;steer=0.
    elif distance<=straight+arc:
        theta=(distance-straight)/radius
        x,y,yaw=-2.5+radius*math.cos(theta),-2.5+radius*math.sin(theta),theta
        steer=math.atan(2.84/radius)
    else:
        x,y,yaw=-2.5-(distance-straight-arc),1.8,math.pi/2;steer=0.
    ped_distance=min(12,max(0,t)*1.8)
    return {'ev':(x,y,yaw),'ev_distance':distance,'steer':steer,'other':(-1.8,16-4*t,math.pi),
            'pedestrian':(4.6-ped_distance,-5.,math.pi/2),'walk_distance':ped_distance,
            'phase':'wait' if t<wait else 'turn','progress':progress}


def circle_clearance(car,point,radius=.4):
    x,y,yaw=car;dx,dy=point[0]-x,point[1]-y
    right=dx*math.cos(yaw)+dy*math.sin(yaw)
    forward=-dx*math.sin(yaw)+dy*math.cos(yaw)
    return math.hypot(max(abs(right)-1.1,0),max(abs(forward)-2.4,0))-radius


def rectangles_overlap(a,b):
    def corners(p):
        x,y,angle=p;c,s=math.cos(angle),math.sin(angle)
        return [(x+rx*c-fy*s,y+rx*s+fy*c) for rx,fy in [(-1.1,-2.4),(1.1,-2.4),(1.1,2.4),(-1.1,2.4)]]
    aa,bb=corners(a),corners(b)
    for angle in [a[2],a[2]+math.pi/2,b[2],b[2]+math.pi/2]:
        axis=(math.cos(angle),math.sin(angle))
        pa=[x*axis[0]+y*axis[1] for x,y in aa];pb=[x*axis[0]+y*axis[1] for x,y in bb]
        if max(pa)<min(pb) or max(pb)<min(pa):return False
    return True

